css:
.toggle-label {
  cursor: pointer;
}

.toggle-container {
  position: relative;
  width: 70px;
  height: 36px;
  border-radius: 20px;
  background: linear-gradient(90deg, #ff0000, #ff7f00);
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2);
  overflow: hidden;
  transition:
    background-color 0.6s ease-in-out,
    box-shadow 0.4s ease;
}

.toggle {
  position: absolute;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: radial-gradient(circle, #fff, #e0e0e0);
  top: 0;
  left: 0;
  transition: transform 0.4s cubic-bezier(0.68, -0.55, 0.27, 1.55);
  box-shadow: inset 0 2px 5px rgba(0, 0, 0, 0.3);
  display: flex;
  justify-content: center;
  align-items: center;
}

.icon {
  position: absolute;
  font-size: 20px;
  transition:
    opacity 0.4s ease,
    transform 0.4s ease;
}

.check {
  opacity: 0;
  transform: scale(0);
}

.cross {
  opacity: 1;
  transform: scale(1);
}

.toggle-input {
  display: none;
}

.toggle-input:checked + .toggle-container {
  background: linear-gradient(90deg, #4caf50, #81c784);
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
}

.toggle-input:checked + .toggle-container .toggle {
  transform: translateX(34px);
}

.toggle-input:checked + .toggle-container .toggle .check {
  opacity: 1;
  transform: scale(1);
}

.toggle-input:checked + .toggle-container .toggle .cross {
  opacity: 0;
  transform: scale(0);
}

.toggle-container:active .toggle {
  transform: scale(0.95);
}
